	#dim %page as %ZEN.Component.page
	set stat = 1
	Try {

		 set un = $get(%session.Data("UsNm"))
		 Set key = $QUERY(^itfDebug(un))

		 Do ##class(IHC.ITF.ITFCOMMON.Utility).WriteToFileWithUserNm(un, "Search itfDebug for " _ un)
		 While (key '= "") {

		     if ( (key [ un))
		     {
			     if ( (@key [ "Unexpected server error") || (@key [ "Internal Server Error"))
			     {
				     set dt = $ZDATETIME($PIECE(key, """", 4),1,3)
				     Set %page.%GetComponentById("svnContent").content = "FATAL SVN ERROR in the Global Data at " _ dt _ "-> " _ @key
				     set stat = 0
				     quit
			     }
		     	// Find next node
		     	Set key = $Query(@key)
		     }
		     else
		     {
			     quit
		     }
		 }
 		Do ##class(IHC.ITF.ITFCOMMON.Utility).WriteToFileWithUserNm(un, "No errors in itfDebug")
		if (stat = 1)
		{
			Do ##class(IHC.ITF.ITFCOMMON.Utility).WriteToFileWithUserNm(un, "Run SVN INFO ")
			set cmd = $$$SVNINFO _ " --username " _ %session.Data("svnUsrNm") _ " --password '" _ %session.Data("svnPsWd") _ "' " _ $$$SVNSRCURL
	        Set stat = ##class(IHC.ITF.SrcCtrlPkg.EnsembleSrcCtrlClass).ExecuteShellCmd(cmd)

	        Do ##class(IHC.ITF.ITFCOMMON.Utility).WriteToFileWithUserNm(un, "Check SVN info: " _ un _ ", stat: " _ stat)
			if (stat '= 0)
			{
				Set %page.%GetComponentById("svnContent").content = "Could not access Subversion, SVN info command failed"
			}
			else
			{
				Set %page.%GetComponentById("svnContent").content = "Subversion is funcational, svn info command by " _ un _ " successful"
			}
		}
		Set %page.%GetComponentById("svnInfoGroup").hidden = 0

	}
	Catch(ex) {
		 Set %page.%GetComponentById("svnContent").content = "Could not run SVN info command, exception: " _ ex
		 Set %page.%GetComponentById("svnInfoGroup").hidden = 0
	}
	Quit stat

