if (zenPage.getComponentById('tabGroup').getCurrTabNo() == 1)
{
	alert('ChangeNS Populate srcCtrlTable - ' + val);
	zenPage.NmSpUpdListOfFilesInSvn();	
	var table = zenPage.getComponentById('srcCtrlTable');
	table.setProperty("selectedRows", "");
	table.executeQuery(true);
}
else
{
	alert('ChangeNS Populate populateComp - ' + val);
	zenPage.populateComp();
}

	try
	{
		var val =  zenPage.getComponentById('nmSpListBox').getValue().trim();
		var compType =  zenPage.getComponentById('compType').getValue();

		zenPage.getComponentById('components').resetOptions();
		zenPage.getComponentById('lblAccess').setValue('Update the components From Ensemble. ' + val)
		zenPage.getComponentById('lblAccess').setProperty('hidden', false);

	    var comps = zenPage.getComponents(val.trim(), compType)
	    entries = comps.split(",");
	    for (i=0; i<entries.length; i++)
		{
	   	  zenPage.getComponentById('components').appendOption(entries[i], entries[i]);
		}
		if(compType == 'All' || compType == 'Service' || compType == 'Operation')
		{
			zenPage.getComponentById('ChangeClass').setProperty('hidden', false);
		}
		else
		{
			zenPage.getComponentById('ChangeClass').setProperty('hidden', true);
		}
		zenPage.getComponentById('fldSetComponents').setProperty('legend', '# of Components: ' + entries.length);
		zenPage.getComponentById('srcCtrlTable').setProperty('caption', 'Files in ' + val);



    }
	catch(ex) {
		 zenPage.getComponentById('lblAccess').setValue( "ChangeNS, exception: " + ex)

	}

	set tSC = $$$OK
	set cmps = ""
	Do ##class(IHC.ITF.ITFCOMMON.Utility).WriteToFileWithUserNm($get(%session.Data("UsNm")), nmSp _ ", " _compType)
	try {
	set %session.Data("NmSp") = nmSp
	Set $NAMESPACE = nmSp

	Set tProductionName = ##class(Ens.Director).GetActiveProductionName()

   		// $$$LOGINFO( "GetComponents " _ $NAMESPACE _ ", getProductionItems: " _ tProductionName)

   		Set tProduction = ##class(Ens.Config.Production).%OpenId(tProductionName,,.tStatus)


   		Set tStatus = ##class(Ens.Director).getProductionItems(tProduction,.tProductionDefinition)

   		If ($DATA(tProductionDefinition) = 10) {
	   		Set tConfigName = ""
			For { 
				Set tConfigName = $ORDER(tProductionDefinition(tConfigName))
				Quit:(tConfigName = "")
				Set tConfigBusinessType = tProductionDefinition(tConfigName,"BusinessType")
				Set tConfigBusinessType = $CASE(tConfigBusinessType,
              							1:"Service",
              							2:"Process",
              							3:"Operation",
              							:"Unknown")
				if ( (compType = "All") || (tConfigBusinessType = compType))
				{				
					set cmps = cmps _ "," _ tConfigName
				}

			}
   		}

	}catch (err)
	{
		Do ##class(IHC.ITF.ITFCOMMON.Utility).WriteToFileWithUserNm($get(%session.Data("UsNm")), "Exception: " + err)
	}
	Do ##class(IHC.ITF.ITFCOMMON.Utility).WriteToFileWithUserNm($get(%session.Data("UsNm")), "Components: " _ cmps)
   	return cmps


   var comp = zenPage.getComponentById('components').getValue();
   var nmSp = zenPage.getComponentById('namespLbl').getValue();

   if(comp == '')
    {
	    comp = zenPage.getComponentById('newComp').getValue();
    }

    if(comp != '')
    {
	   try
	    {		    
   			var statStr = zenPage.FindDeploymentFiles(comp, nmSp);

	   		zenPage.getComponentById('lblAccess').setValue(statStr);

	    } catch(err)
	    {
		    zenPage.getComponentById('lblAccess').setValue('Exception: ' + err.message);
	    }
    }
    else
    {
	    zenPage.getComponentById('lblAccess').setValue('Component name is required')
    }


set retStr = ""
set verStr = ""
try {

	set comp = $ZSTRIP(comp,"<>WC")

	set createDeployCls = ##class(IHC.ITF.SrcCtrlPkg.CreateDeploymentFiles).%New()
	set verStr = createDeployCls.GetVersions(comp, $get(%session.Data("UsNm")), $get(%session.Data("svnPsWd")), 1 )
	if ($L(verStr) <= 0)
	{
		set retStr = "Could not find Deployment files for " _ comp
	}
	else
	{

		set retStr = "<BR><B> Last Ensemble Deployment:</B><BR><BR><table border=""1"">"
		set retStr = retStr _ "<TR><TH>Env</TH><TH>Revision # </TH><TH>Impl Date </TH> <TH>Impl File </TH></TR>"
		set retStr = retStr _ "<TR><TD>PROD </TD> " _ ..GetDeployments(comp, nmSp, "PROD")
		set retStr = retStr _ "</TR><TR><TD>UAT  </TD> " _ ..GetDeployments(comp, nmSp, "UAT")
		set retStr = retStr _ "</TR><TR><TD>QA   </TD> " _ ..GetDeployments(comp, nmSp, "QA")
		set retStr = retStr _ "</TR></Table><BR><BR><B> Subversion check-ins: </B><BR><BR>"
		set retStr = retStr _ verStr
		if ( $FIND(retStr, "Last Changed Rev") > 0)
		{
			set retStr = $REPLACE(retStr, "Last Changed Rev", "<B>Last Changed Rev</B>", 0, 1, 1)
		}
		if ( $FIND(retStr, "Commited by") > 0)
		{
			set retStr = $REPLACE(retStr, "Commited by", "<B><I>Commited by</I></B>", 0, 1, 1)
		}

	}


} catch(err)
{
	set retStr = "Exception: Could not find Deployment files " _ err.Data _" - " _ comp _ ", " _ verStr
}

Return retStr


  set depCl = ##class(SrcCtrlDeploymentInfoWebService.SrcCtrlDeploymentInfoWebServiceSoap).%New()
  set depCl.Username = %session.Data("srcHistUsrNm")
  set depCl.Password = %session.Data("srcHistPsWd")
  Set depCl.SSLConfiguration = "DeployClientService"
  Try {
  	Do depCl.WSSecurityLogin(depCl.Username,depCl.Password)
  } Catch ex {
  	Set errorMsg = "Error: "_ex.DisplayString()
  	Do ##class(IHC.ITF.ITFCOMMON.Utility).WriteToFileWithUserNm($USERNAME, errorMsg)
  }


  try
