  Set depCl.Location = ..WSLocation
  set compImpl = depCl.GetLastImplementationDetails(tItemName, env, nmSp)

   Set tExportClsFilename = $P(compImpl, ";", 1)
  Set rev = $P(compImpl, ";", 2)
  set details =  "<TD>" _ rev _ "</TD><TD> " _  $P(compImpl, ";", 3) _ "</TD><TD> " _ tExportClsFilename _"</TD>"
  // WRITE !,  details

